193→    }
194→  }, []);
195→
196→  const handleContentDragLeave = useCallback((e: DragEvent) => {
197→    if (isExternalFileDrag(e.dataTransfer)) {
198→      dragCounterRef.current -= 1;
199→      if (dragCounterRef.current <= 0) {
200→        dragCounterRef.current = 0;
