224→    window.addEventListener('drop', handleWindowDrop);
225→    window.addEventListener('dragleave', handleWindowDragLeave as EventListener);
226→    return () => {
227→      window.removeEventListener('dragend', resetDragState);
228→      window.removeEventListener('drop', handleWindowDrop);
229→      window.removeEventListener('dragleave', handleWindowDragLeave as EventListener);
230→    };
231→  }, []);
