 13→import { useSharedNavigation, type SharedListItem } from '../../hooks/useSharedNavigation';
 14→import { useContextMenu } from '../../hooks/useContextMenu';
 15→import {
 16→  isFilePointer,
 17→  isTextFile,
 18→  isImageFile,
 19→  isPdfFile,
 20→  isAudioFile,
 21→  isVideoFile,
 22→  isPreviewableFile,
 23→} from '../../utils/fileTypes';
 24→import { ContextMenu } from './ContextMenu';
 25→import { DetailsDialog } from './DetailsDialog';
 26→import { ImagePreviewDialog } from './ImagePreviewDialog';
 27→import { PdfPreviewDialog } from './PdfPreviewDialog';
 28→import { AudioPlayerDialog } from './AudioPlayerDialog';
 29→import { VideoPlayerDialog } from './VideoPlayerDialog';
 30→import { TextEditorDialog } from './TextEditorDialog';
 31→import '../../styles/shared-browser.css';
 32→
 33→/**
 34→ * Truncate a public key for display: 0x{first4}...{last4}
 35→ */
 36→function truncatePubkey(pubkey: string): string {
 37→  if (pubkey.length <= 12) return pubkey;
 38→  const hex = pubkey.startsWith('0x') ? pubkey.slice(2) : pubkey;
 39→  return `0x${hex.slice(0, 4)}...${hex.slice(-4)}`;
 40→}
 41→
 42→/**
 43→ * Sort items: folders first, then files, both alphabetically.
 44→ */
 45→function sortItems(items: FolderChild[]): FolderChild[] {
 46→  return [...items].sort((a, b) => {
 47→    if (a.type === 'folder' && b.type !== 'folder') return -1;
 48→    if (a.type !== 'folder' && b.type === 'folder') return 1;
 49→    return a.name.localeCompare(b.name, undefined, { sensitivity: 'base' });
 50→  });
 51→}
 52→
 53→type DialogState = {
 54→  open: boolean;
 55→  item: FolderChild | null;
 56→};
 57→
 58→/**
 59→ * Terminal-style ASCII art for shared empty state.
 60→ */
 61→const sharedEmptyArt = `\u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510
 62→\u2502 $ ls ~/shared        \u2502
 63→\u2502 total 0              \u2502
 64→\u2502 $ \u2588                  \u2502
 65→\u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518`;
