  3→/** Extensions recognized as editable text files. */
  4→const TEXT_EXTENSIONS = new Set([
  5→  '.txt',
  6→  '.md',
  7→  '.json',
  8→  '.yaml',
  9→  '.yml',
 10→  '.toml',
 11→  '.xml',
 12→  '.csv',
 13→  '.log',
 14→  '.env',
 15→  '.sh',
 16→  '.bash',
 17→  '.zsh',
 18→  '.fish',
 19→  '.ps1',
 20→  '.bat',
 21→  '.cmd',
 22→  '.ini',
 23→  '.cfg',
 24→  '.conf',
 25→  '.html',
 26→  '.htm',
 27→  '.css',
 28→  '.scss',
 29→  '.less',
 30→  '.js',
 31→  '.mjs',
 32→  '.cjs',
 33→  '.ts',
 34→  '.mts',
 35→  '.cts',
 36→  '.jsx',
 37→  '.tsx',
 38→  '.py',
 39→  '.rb',
 40→  '.rs',
 41→  '.go',
 42→  '.java',
 43→  '.c',
 44→  '.cpp',
 45→  '.h',
 46→  '.hpp',
 47→  '.sql',
 48→  '.graphql',
 49→  '.gitignore',
 50→  '.editorconfig',
 51→]);
 52→
 53→/** Well-known extensionless text filenames. */
 54→const TEXT_FILENAMES = new Set([
 55→  'dockerfile',
 56→  'makefile',
 57→  'rakefile',
 58→  'gemfile',
 59→  'procfile',
 60→  'vagrantfile',
 61→]);
 62→
 63→/** Extensions recognized as previewable image files. */
 64→const IMAGE_EXTENSIONS = new Set([
 65→  '.png',
 66→  '.jpg',
 67→  '.jpeg',
 68→  '.gif',
 69→  '.webp',
 70→  '.svg',
 71→  '.bmp',
 72→  '.ico',
 73→  '.avif',
 74→]);
 75→
 76→/** Extensions recognized as PDF files. */
 77→const PDF_EXTENSIONS = new Set(['.pdf']);
 78→
 79→/** Extensions recognized as playable audio files. */
 80→const AUDIO_EXTENSIONS = new Set(['.mp3', '.wav', '.ogg', '.m4a', '.flac']);
 81→
 82→/** Extensions recognized as playable video files. */
 83→const VIDEO_EXTENSIONS = new Set(['.mp4', '.webm', '.mov', '.mkv']);
 84→
 85→function getExtension(name: string): string | null {
 86→  const lower = name.toLowerCase();
 87→  const lastDot = lower.lastIndexOf('.');
 88→  if (lastDot === -1) return null;
 89→  return lower.slice(lastDot);
 90→}
 91→
 92→/** Check if a filename has a text-editable extension. */
 93→export function isTextFile(name: string): boolean {
 94→  const lower = name.toLowerCase();
 95→  if (TEXT_EXTENSIONS.has(lower)) return true;
 96→  if (TEXT_FILENAMES.has(lower)) return true;
 97→  const ext = getExtension(name);
 98→  return ext !== null && TEXT_EXTENSIONS.has(ext);
 99→}
100→
101→/** Check if a filename has a previewable image extension. */
102→export function isImageFile(name: string): boolean {
103→  const ext = getExtension(name);
104→  return ext !== null && IMAGE_EXTENSIONS.has(ext);
105→}
106→
107→/** Check if a filename has a PDF extension. */
108→export function isPdfFile(name: string): boolean {
109→  const ext = getExtension(name);
110→  return ext !== null && PDF_EXTENSIONS.has(ext);
111→}
112→
113→/** Check if a filename has a playable audio extension. */
114→export function isAudioFile(name: string): boolean {
115→  const ext = getExtension(name);
116→  return ext !== null && AUDIO_EXTENSIONS.has(ext);
117→}
118→
119→/** Check if a filename has a playable video extension. */
120→export function isVideoFile(name: string): boolean {
121→  const ext = getExtension(name);
122→  return ext !== null && VIDEO_EXTENSIONS.has(ext);
123→}
124→
125→/** Check if a filename is any previewable type (image, PDF, audio, video). */
126→export function isPreviewableFile(name: string): boolean {
127→  return isImageFile(name) || isPdfFile(name) || isAudioFile(name) || isVideoFile(name);
128→}
129→
130→/** Type guard: narrows FolderChild to FilePointer by checking type discriminant. */
131→export function isFilePointer(item: FolderChild): item is FilePointer {
132→  return item.type === 'file';
133→}
