 55→/**
 56→ * Main file browser container component.
 57→ *
 58→ * Manages the file list area with in-place navigation.
 59→ * Selection state, context menu, and file/folder actions.
 60→ *
 61→ * Navigation:
 62→ * - Double-click folders to navigate into them
 63→ * - Click [..] PARENT_DIR row to navigate up
 64→ * - Browser history integration via URL routing
 65→ *
 66→ * Actions:
 67→ * - Download: Downloads file from IPFS, decrypts, and triggers browser download
 68→ * - Rename: Opens dialog to rename file/folder
 69→ * - Delete: Shows confirmation, then removes from folder metadata
 70→ * - Move: Drag-drop to folder rows in list
 71→ *
 72→ * @example
 73→ * ```tsx
 74→ * function FilesPage() {
 75→ *   return (
 76→ *     <main className="app-main">
 77→ *       <FileBrowser />
 78→ *     </main>
 79→ *   );
 80→ * }
 81→ * ```
 82→ */
 83→
 84→export function FileBrowser() {
 85→  // Navigation state from hook
 86→  const { currentFolderId, currentFolder, breadcrumbs, isLoading, navigateTo, navigateUp } =
 87→    useFolderNavigation();
 88→
 89→  // Folder operations
 90→  const {
 91→    createFolder,
 92→    renameItem,
 93→    moveItem,
 94→    moveItems,
 95→    deleteItem,
 96→    deleteItems,
 97→    isLoading: isOperating,
 98→  } = useFolder();
 99→
100→  // File download
101→  const { downloadFromIpns, isDownloading } = useFileDownload();
102→
103→  // External file drop upload
104→  const { handleFileDrop } = useDropUpload();
105→
106→  // Context menu state
107→  const contextMenu = useContextMenu();
108→
109→  // Vault and folder stores for sync
110→  const { rootIpnsName } = useVaultStore();
111→  const initialSyncComplete = useSyncStore((state) => state.initialSyncComplete);
112→  const syncStatus = useSyncStore((state) => state.status);
113→
114→  // Sync callback - compare remote sequence with local, refresh if different
115→  const handleSync = useCallback(async () => {
116→    if (!rootIpnsName) return;
117→
118→    // Resolve root folder IPNS to get remote CID and sequence number
119→    // Note: resolveIpnsRecord returns null when the record definitively
120→    // doesn't exist (backend 404 / success:false). Transient failures
121→    // (network errors, 5xx) throw instead, which useSyncPolling catches.
122→    const resolved = await resolveIpnsRecord(rootIpnsName);
123→    if (!resolved) {
124→      // No IPNS record found. This is expected for vaults that have
125→      // never published (empty vault, no uploads yet). Return normally
126→      // so useSyncPolling marks initial sync complete and shows the
127→      // empty file browser instead of retrying forever.
128→      return;
129→    }
130→
131→    // Read fresh state from store — avoid stale closure from render cycle.
132→    // On initial load, the root folder may not be in the closure's `folders`
133→    // yet because useFolderNavigation's useEffect sets it in the same commit.
134→    const rootFolder = useFolderStore.getState().folders['root'];
135→    if (!rootFolder) return;
136→
137→    // Compare sequence numbers - if remote > local, we need to refresh
138→    // Sequence number comparison is more reliable than CID since we
139→    // don't cache the local CID, and sequence always increments
140→    if (resolved.sequenceNumber <= rootFolder.sequenceNumber) {
141→      // No changes, already up to date
142→      return;
143→    }
144→
145→    // Remote has newer version - fetch and decrypt new metadata
146→    try {
147→      const metadata = await fetchAndDecryptMetadata(resolved.cid, rootFolder.folderKey);
148→
149→      // Update folder store with new children
150→      // Per CONTEXT.md: last write wins, instant refresh (no toast/prompt)
151→      useFolderStore.getState().updateFolderChildren('root', metadata.children);
152→      useFolderStore.getState().updateFolderSequence('root', resolved.sequenceNumber);
153→
154→      // Rebuild search index with updated folder data
155→      triggerSearchIndexRebuild();
156→    } catch (err) {
157→      console.error('Sync refresh failed:', err);
158→      // During initial sync, propagate so useSyncPolling keeps the
159→      // loading UI visible and retries instead of showing empty state
160→      if (!useSyncStore.getState().initialSyncComplete) {
161→        throw err;
162→      }
163→    }
164→  }, [rootIpnsName]);
165→
166→  // Start sync polling (30s interval, pauses when backgrounded/offline)
167→  useSyncPolling(handleSync);
168→
169→  // Device registry polling (60s interval, independent from vault sync)
170→  useDeviceRegistrySync();
171→
172→  // External drag state — tracks when files from OS are being dragged over
173→  const [isDraggingExternal, setIsDraggingExternal] = useState(false);
174→  const dragCounterRef = useRef(0);
175→
176→  /**
177→   * Detect external file drag entering the content area.
178→   * Uses a counter to handle nested dragenter/dragleave events correctly.
179→   */
180→  const handleContentDragEnter = useCallback((e: DragEvent) => {
181→    if (isExternalFileDrag(e.dataTransfer)) {
182→      dragCounterRef.current += 1;
183→      if (dragCounterRef.current === 1) {
184→        setIsDraggingExternal(true);
185→      }
186→    }
187→  }, []);
188→
189→  const handleContentDragOver = useCallback((e: DragEvent) => {
190→    if (isExternalFileDrag(e.dataTransfer)) {
191→      e.preventDefault();
192→      e.dataTransfer.dropEffect = 'copy';
193→    }
194→  }, []);
195→
196→  const handleContentDragLeave = useCallback((e: DragEvent) => {
197→    if (isExternalFileDrag(e.dataTransfer)) {
198→      dragCounterRef.current -= 1;
199→      if (dragCounterRef.current <= 0) {
200→        dragCounterRef.current = 0;
201→        setIsDraggingExternal(false);
202→      }
203→    }
204→  }, []);
205→
206→  // Reset drag state if user abandons drag outside the window (e.g. drops on desktop
207→  // or presses Escape). Without this the counter/overlay can get stuck.
208→  useEffect(() => {
209→    const resetDragState = () => {
