 1→import { useState, useCallback } from 'react';
 2→import type { FolderChild } from '@cipherbox/crypto';
 3→
 4→/**
 5→ * Context menu state shape.
 6→ */
 7→type ContextMenuState = {
 8→  visible: boolean;
 9→  x: number;
10→  y: number;
11→  item: FolderChild | null;
12→};
13→
14→/**
15→ * Hook for managing context menu state.
16→ *
17→ * Provides show/hide functionality with position and item tracking.
18→ *
19→ * @example
20→ * ```tsx
21→ * function FileList() {
22→ *   const contextMenu = useContextMenu();
23→ *
24→ *   const handleContextMenu = (e: MouseEvent, item: FolderChild) => {
25→ *     contextMenu.show(e, item);
26→ *   };
27→ *
28→ *   return (
29→ *     <>
30→ *       {contextMenu.visible && (
31→ *         <ContextMenu
32→ *           x={contextMenu.x}
33→ *           y={contextMenu.y}
34→ *           item={contextMenu.item!}
35→ *           onClose={contextMenu.hide}
36→ *         />
37→ *       )}
38→ *     </>
39→ *   );
40→ * }
41→ * ```
42→ */
43→export function useContextMenu() {
44→  const [state, setState] = useState<ContextMenuState>({
45→    visible: false,
46→    x: 0,
47→    y: 0,
48→    item: null,
49→  });
50→
51→  /**
52→   * Show context menu at the event position for the given item.
53→   */
54→  const show = useCallback((event: React.MouseEvent, item: FolderChild) => {
55→    event.preventDefault();
56→    event.stopPropagation();
57→    setState({
58→      visible: true,
59→      x: event.clientX,
60→      y: event.clientY,
61→      item,
62→    });
63→  }, []);
64→
65→  /**
66→   * Hide the context menu.
67→   */
68→  const hide = useCallback(() => {
69→    setState((prev) => ({
70→      ...prev,
71→      visible: false,
72→    }));
73→  }, []);
74→
75→  return {
76→    visible: state.visible,
77→    x: state.x,
78→    y: state.y,
79→    item: state.item,
80→    show,
81→    hide,
82→  };
83→}
